  ('af9190b3-307d-450e-b4cc-2862af1a70e6', $$Biologie$$, $$VWO$$, $$Bloedplaatjes belaagd$$, $$VWO Biologie 2026-I$$),
  ('69321ec2-db40-47bf-ad44-ae7bae98d021', $$Biologie$$, $$VWO$$, $$Synthetische biologie: ombouwen van E. coli$$, $$VWO Biologie 2026-I$$),
  ('58a83532-6fbe-4f00-86da-47ecf3f6d400', $$Biologie$$, $$VWO$$, $$Imker door bijensteken naar de eerste hulp$$, $$VWO Biologie 2026-I$$),
  ('4d01e2c8-3f82-43ae-b31d-0ee6388ccc83', $$Biologie$$, $$VWO$$, $$CRISPR in de strijd tegen overgewicht$$, $$VWO Biologie 2026-I$$),
