insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('f2491363-89fd-4ce3-8285-ccaef940f434', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$inleiding: bij Rosies geboorte vallen rode en paarse vlekjes over haar hele lichaam op$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context1.png$$,
   $$Toen Rosie werd geboren, viel het de verloskundige op dat ze rode en paarse vlekjes had over haar hele lichaam.$$, 'inline'),
  ('31898dfd-969c-4dda-83d8-45879c4775af', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$informatiekader: trombocytopenie (tekort aan bloedplaatjes) veroorzaakt bloeduitstortinkjes$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context2.png$$,
   $$In het ziekenhuis werd de samenstelling van Rosies bloed bekeken. Het bleek dat ze een vorm van trombocytopenie heeft, een tekort aan bloedplaatjes. De paarse vlekjes bij Rosie zijn kleine bloedingen in de huid (bloeduitstortinkjes).$$, 'inline'),
  ('8dc4ca11-6f80-4e02-b90c-3b700895f60a', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$bloedplaatjes houden de cell junctions tussen endotheelcellen van bloedvaten intact$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context3.png$$,
   $$Bloedplaatjes zorgen voor de instandhouding van de cell junctions: de verbindingen tussen de endotheelcellen (dekweefselcellen) van de bloedvaten.$$, 'inline'),
  ('00e17aaa-6804-4c84-9228-086c904e9988', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$bloedplaatjes ontstaan uit megakaryoblasten in het rode beenmerg onder invloed van TPO$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context4.png$$,
   $$Bloedplaatjes ontstaan in het rode beenmerg. Bij de differentiatie van megakaryoblasten ontstaan grote cellen die uiteindelijk uiteenvallen in kleine blaasjes zonder celkern: de bloedplaatjes. De rijping van de megakaryoblasten wordt gestimuleerd door het signaaleiwit TPO. Een terugkoppelingsmechanisme met het aantal bloedplaatjes zorgt ervoor dat in een gezonde situatie de concentratie bloedplaatjes in het bloed stabiel blijft.$$, 'inline'),
  ('46d20ebb-e6da-4f5c-90a8-d8c90ff095bc', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$microscopische preparaten van normaal bloed en van bloed van Rosie$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context5.png$$,
   $$Om de trombocytopenie bij Rosie vast te stellen, is het aantal bloedplaatjes in het bloed bepaald. Door toevoeging van een kleurstof aan een microscopisch preparaat van bloed, worden bloedplaatjes zichtbaar als donkere vlekken. In de afbeelding zijn een microscopisch preparaat van normaal bloed en een microscopisch preparaat van het bloed van Rosie weergegeven.
normaal bloed bloed Rosie$$, 'inline'),
  ('117e267e-29e4-4b20-82a7-fbaa065a2dcb', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$tekort aan bloedplaatjes geeft verminderde bloedstolling; stoffen betrokken bij bloedstolling$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context6.png$$,
   $$Door het tekort aan bloedplaatjes treedt bij Rosie tijdens een bloeding verminderde bloedstolling op. Interne bloedingen zouden daardoor ernstige gevolgen hebben voor Rosie. Hieronder staan enkele stoffen die betrokken zijn bij bloedstolling.
1 protrombine
2 trombine
3 fibrinogeen
4 fibrine Bij Rosie zal de concentratie van een aantal van deze stoffen lager zijn dan bij een gezonde persoon.$$, 'inline'),
  ('3aaeae07-eaee-4049-9882-2a23e88dd7db', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$informatiekader: HPA-antigenen op bloedplaatjes; allelen en allelfrequenties van HPA1-gen en HPA5-gen (tabel 1)$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context7.png$$,
   $$Nadat andere oorzaken werden uitgesloten, vermoedden de artsen dat bij Rosie sprake was van een afweerreactie tegen de antigenen op haar bloedplaatjes. Deze antigenen worden HPA’s (human platelet antigens) genoemd. Elk bloedplaatje heeft een aantal verschillende HPA’s. Van de genen die coderen voor deze HPA’s, komen alle aanwezige allelen tot expressie. In tabel 1 zie je gegevens van twee van deze genen.
tabel 1
gen chromosoom- allel antigeen allelfrequentie in nummer Noordwest-Europa HPA1-gen 17 1a HPA-1a 0,84 1b HPA-1b 0,16 HPA5-gen 5 5a HPA-5a 0,92 5b HPA-5b 0,08$$, 'inline'),
  ('9f1b33d1-9682-4897-ab7e-7bc6c3bd1940', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$HPA-1a en HPA-1b verschillen één aminozuur door een puntmutatie; uitspraken over de mutatie$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context8.png$$,
   $$HPA-1a en HPA-1b bestaan beide uit 762 aminozuren. Het verschil tussen HPA-1a en HPA-1b is slechts één aminozuur: op positie 33 is bij HPA-1a leucine ingebouwd; bij HPA-1b proline. Dit is het gevolg van een puntmutatie in het HPA1-gen. Hieronder staan uitspraken over de mutatie.
1 De mutatie kan een insertie zijn.
2 De mutatie bevindt zich in een intron.
3 De mutatie betreft de derde base in het coderende triplet.$$, 'inline'),
  ('16a48fb9-1cbe-46cd-a6f7-0064e987edc8', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$informatiekader: afweerreactie bij de moeder als bloedplaatjes van het kind in haar bloed terechtkomen$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context9.png$$,
   $$Als de antigenen op de bloedplaatjes van het kind verschillen van die van de moeder, en er – bijvoorbeeld tijdens de bevalling – bloedplaatjes van het kind in het bloed van de moeder terechtkomen, ontstaat er bij de moeder een afweerreactie waarbij antistoffen worden gevormd. Hierdoor kan trombocytopenie optreden bij een volgend kind.$$, 'inline'),
  ('c646e34e-d6e3-4aac-905a-9563d666c9f2', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$informatiekader: HPA-1a komt ook tot expressie in endotheelcellen van het placentaweefsel$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context10.png$$,
   $$HPA-1a komt ook tot expressie in endotheelcellen van het placenta- weefsel van de foetus. Hierdoor komt trombocytopenie soms al tijdens de eerste zwangerschap voor.$$, 'inline'),
  ('50fe0454-0d64-4162-b476-7ecfb0bfe24a', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$activering van het immuunsysteem van de moeder vereist antigeen, APC’s en T-helpercellen$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context11.png$$,
   $$Als het immuunsysteem van de moeder geactiveerd wordt, zijn daarbij een antigeen, antigeen-presenterende cellen (APC’s) en T-helpercellen betrokken.$$, 'inline'),
  ('3a595190-3f57-434a-98a6-71f414a797c0', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$Rosie kreeg een infuus met bloedplaatjes zonder HPA-1a$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context12.png$$,
   $$Om het tekort aan bloedplaatjes op te vangen, kreeg Rosie een infuus met bloedplaatjes. Omdat nog niet bekend was welke antistoffen bij Rosie aanwezig waren, werd gekozen voor bloedplaatjes zonder HPA-1a. De kans is namelijk het grootst dat de trombocytopenie wordt veroorzaakt door antistoffen tegen HPA-1a.$$, 'inline'),
  ('eec90da2-aa9c-43fd-a389-d8094fb64d0a', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$informatiekader: Rosies bloed bevat antistoffen tegen HPA-1a en HPA-5b; genotype wijkt af van dat van haar moeder$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context13.png$$,
   $$Uit het bloedonderzoek bleek dat Rosies bloed antistoffen bevat tegen HPA-1a en tegen HPA-5b. Ook werd haar genotype en dat van haar ouders bepaald. Rosie bleek een ander genotype voor HPA-1 en HPA-5 te hebben dan haar moeder. Daaruit concludeerden de artsen dat de trombocytopenie bij Rosie werd veroorzaakt door antistoffen die ze van haar moeder had gekregen tijdens de zwangerschap.$$, 'inline'),
  ('57580eb5-ab9e-4e37-b404-77ccc8120ba0', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$de afweerreactie bij Rosie wordt allo-immuniteit genoemd$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context14.png$$,
   $$De afweerreactie die door de antistoffen wordt veroorzaakt in het lichaam van Rosie wordt allo-immuniteit genoemd.$$, 'inline'),
  ('543cb30c-d8fe-4efc-943d-3a3fcfbaa458', 'af9190b3-307d-450e-b4cc-2862af1a70e6', $$Rosies vader heeft genotype 1a1b 5a5b$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-context15.png$$,
   $$Rosies vader heeft genotype 1a1b 5a5b. Met de informatie in het kader boven vraag 10 zijn ook de genotypen van Rosie en van Rosies moeder af te leiden voor de genen die coderen voor HPA-1 en HPA-5.$$, 'inline'),
  ('9a75032b-eb4b-47ee-88c3-b6b29b68a372', '69321ec2-db40-47bf-ad44-ae7bae98d021', $$inleiding: onderzoek naar de stappen om een heterotrofe bacterie om te bouwen tot chemo-autotrofe bacterie$$,
   $$biologie-vwo-2026-i-synthetische-biologie-ombouwen-van-e-coli-context1.png$$,
   $$Biologen hebben onderzocht welke stappen nodig zijn om een heterotrofe bacterie om te bouwen tot een chemo-autotrofe bacterie.$$, 'inline'),
  ('1c1d0cfb-9ebc-4b17-aac1-15ef61984fac', '69321ec2-db40-47bf-ad44-ae7bae98d021', $$informatiekader: de darmbacterie Escherichia coli (heterotroof, aerobe en anaerobe dissimilatie, effect op de mens)$$,
   $$biologie-vwo-2026-i-synthetische-biologie-ombouwen-van-e-coli-context2.png$$,
   $$De biologen gebruikten voor hun onderzoek de darmbacterie Escherichia coli. Het genoom van deze bacterie is bekend, en de bacterie is snel en eenvoudig te kweken. E. coli is heterotroof en kan zowel aerobe als anaerobe dissimilatie uitvoeren. In de darmen van mensen bevordert E. coli de vertering en produceert B-vitamines en vitamine K. Sommige varianten van de bacterie zijn voor mensen ziekmakend.$$, 'inline'),
  ('918fafdd-15bd-4b42-a87a-c6878cc444c3', '69321ec2-db40-47bf-ad44-ae7bae98d021', $$symbiose tussen de mens en niet-ziekmakende en ziekmakende E. coli-varianten$$,
   $$biologie-vwo-2026-i-synthetische-biologie-ombouwen-van-e-coli-context3.png$$,
   $$Uit de tekst blijkt dat er sprake is van symbiose tussen de verschillende E. coli-varianten en de mens:
1 tussen de mens en niet-ziekmakende varianten;
2 tussen de mens en ziekmakende varianten.$$, 'inline'),
  ('287bafc3-8088-4331-8f77-42a1f589ce2c', '69321ec2-db40-47bf-ad44-ae7bae98d021', $$informatiekader: genen van de calvincyclus (Pseudomonas) en het enzym FDH ingebracht; stofwisselingsprocessen in de autotrofe E. coli (afbeelding 1)$$,
   $$biologie-vwo-2026-i-synthetische-biologie-ombouwen-van-e-coli-context4.png$$,
   $$Om E. coli autotroof te maken, brachten de biologen genen in die coderen voor enkele enzymen van de calvincyclus. Deze genen zijn afkomstig van de bacterie Pseudomonas. Ook werd een gen ingebracht dat codeert voor het enzym FDH. Door dit enzym kan de stof methaanzuur dienen als donor van energierijke elektronen.
In afbeelding 1 zijn de afbeelding 1 stofwisselingsprocessen in de autotrofe E. coli-bacterie weergegeven zoals de onderzoekers die ontworpen hadden. In het kweekmedium zijn methaanzuur en zuurstof voldoende aanwezig.
In afbeelding 1 staan de stoffen Q en R, en het proces S dat op de celmembraan plaatsvindt.$$, 'inline'),
  ('75f33908-29b7-4367-8189-1a45d967541e', '69321ec2-db40-47bf-ad44-ae7bae98d021', $$de aanpassingen aan E. coli zijn een voorbeeld van genetische modificatie$$,
   $$biologie-vwo-2026-i-synthetische-biologie-ombouwen-van-e-coli-context5.png$$,
   $$De aanpassingen die de biologen deden aan E. coli zijn een voorbeeld van genetische modificatie.$$, 'inline'),
  ('15f148d7-af57-41c7-860e-5c36f50a2f3f', '69321ec2-db40-47bf-ad44-ae7bae98d021', $$methaanzuur is bij de gemodificeerde E. coli de elektronendonor voor de calvincyclus$$,
   $$biologie-vwo-2026-i-synthetische-biologie-ombouwen-van-e-coli-context6.png$$,
   $$Bij de gemodificeerde E. coli is methaanzuur de donor van elektronen voor het verloop van de calvincyclus.$$, 'inline'),
  ('f1c079ad-8062-4739-bb90-691b5b8ea71b', '69321ec2-db40-47bf-ad44-ae7bae98d021', $$informatiekader: glycolysegenen uitgeschakeld; kweek in bioreactor met methaanzuur en afgebouwde xylose (afbeelding 2)$$,
   $$biologie-vwo-2026-i-synthetische-biologie-ombouwen-van-e-coli-context7.png$$,
   $$De volgende stap was het stimuleren van de autotrofe levenswijze van E. coli. Dit kan worden bereikt door ervoor te zorgen dat E. coli geen glucose meer kan gebruiken voor de productie van ATP. De biologen schakelden daartoe drie genen uit die coderen voor enzymen die betrokken zijn bij de glycolyse. Vervolgens werd deze gemodificeerde E. coli gekweekt in een bioreactor (afbeelding 2) waaraan continu een voedingsmedium werd toegevoegd. Dit bevatte onder andere methaanzuur en de monosacharide xylose. Xylose was nodig om ervoor te zorgen dat de bacteriën afbeelding 2 niet meteen zouden sterven aan energiegebrek. E. coli kan xylose namelijk omzetten in pyrodruivenzuur zonder daarbij gebruik te maken van de glycolyse. Tijdens de kweekperiode werd de hoeveelheid xylose in het voedingsmedium geleidelijk afgebouwd naar nul. Vanaf de bodem van de reactor werd lucht met CO₂ toegevoegd.
De E. coli-bacteriën waarmee werd gestart, hadden nog veel stofwisselingsprocessen die passen bij een heterotrofe levenswijze. Na 300 dagen waren de bacteriën in de bioreactor echter volledig autotroof.$$, 'inline'),
  ('cb2f7edb-5e0d-4782-9273-f199d55e845e', '69321ec2-db40-47bf-ad44-ae7bae98d021', $$informatiekader: onderzoek met ¹³C-gelabelde koolstofverbindingen in vier groepen en een positieve controle (afbeelding 3)$$,
   $$biologie-vwo-2026-i-synthetische-biologie-ombouwen-van-e-coli-context8.png$$,
   $$De biologen wilden weten of de gemodificeerde E. coli-bacteriën aan het einde van de kweekperiode alleen CO₂ gebruikten als koolstofbron. Om dat te onderzoeken, gebruikten ze koolstofverbindingen die gelabeld waren met de koolstofisotoop ¹³C.
Ze maakten vier groepen die ze gelabeld of ongelabeld CO₂, en gelabeld of ongelabeld methaanzuur gaven. Als positieve controle was er een vijfde groep met normale (wildtype) E. coli-bacteriën die gelabelde glucose kregen. De vijf groepen bacteriën werden in aparte proefopstellingen gedurende tien generaties verder gekweekt. Na afloop werd het aandeel ¹³C in de aminozuren gemeten. De resultaten van deze proeven zijn weergegeven in afbeelding 3.
afbeelding 3$$, 'inline'),
  ('11f082f1-08b5-40c0-9c38-7d74491a2ea6', '69321ec2-db40-47bf-ad44-ae7bae98d021', $$de positieve controle met wildtype E. coli toont dat ¹³C uit glucose in aminozuren terechtkomt$$,
   $$biologie-vwo-2026-i-synthetische-biologie-ombouwen-van-e-coli-context9.png$$,
   $$E. coli maakt aminozuren van glucose en anorganische stoffen uit het voedingsmedium. De positieve controle met wildtype E. coli laat zien dat de ¹³C uit de glucose inderdaad terechtkomt in aminozuren.$$, 'inline'),
  ('9c1fd5e7-6bcd-4e53-88cd-b8cae2232e7c', '69321ec2-db40-47bf-ad44-ae7bae98d021', $$gemeten percentage ¹³C in aminozuren is gecorrigeerd voor een aanvankelijk hoger percentage$$,
   $$biologie-vwo-2026-i-synthetische-biologie-ombouwen-van-e-coli-context10.png$$,
   $$De biologen maten bij gebruik van CO₂ en ¹³C-methaanzuur aanvankelijk een hoger percentage ¹³C in aminozuren. De waarde die je ziet in afbeelding 3 is hiervoor gecorrigeerd.$$, 'inline'),
  ('15d925cb-0917-42a2-8d9e-f9c534c8a536', '58a83532-6fbe-4f00-86da-47ecf3f6d400', $$inleiding: imker Bert krijgt na meerdere bijensteken een allergische reactie met een opgezwollen gezicht$$,
   $$biologie-vwo-2026-i-imker-door-bijensteken-naar-de-eerste-hulp-context1.png$$,
   $$Imker Bert werd bij de spoedeisende hulp van een ziekenhuis binnengebracht nadat hij meerdere keren was gestoken door zijn bijen. Dit veroorzaakte een allergische reactie waardoor zijn hele gezicht opzwol.$$, 'inline'),
  ('f538902c-882b-407a-a16a-c51042e7e45c', '58a83532-6fbe-4f00-86da-47ecf3f6d400', $$informatiekader: antigenen uit bijengif binden aan witte bloedcellen waardoor histamine vrijkomt$$,
   $$biologie-vwo-2026-i-imker-door-bijensteken-naar-de-eerste-hulp-context2.png$$,
   $$De allergische reactie bij Bert was het gevolg van het binden van antigenen uit het bijengif aan bepaalde witte bloedcellen, waardoor de mediator histamine vrijkomt.$$, 'inline'),
  ('3ce205a2-c6c7-429e-9e1c-8816fa1945c4', '58a83532-6fbe-4f00-86da-47ecf3f6d400', $$de zwellingen in Berts gezicht zijn het gevolg van oedeemvorming$$,
   $$biologie-vwo-2026-i-imker-door-bijensteken-naar-de-eerste-hulp-context3.png$$,
   $$De zwellingen in Berts gezicht zijn het gevolg van oedeemvorming.$$, 'inline'),
  ('671e7da5-b9bb-4ea5-b9b3-bece1f370429', '58a83532-6fbe-4f00-86da-47ecf3f6d400', $$bij eerdere bijensteken was er geen sprake van een allergische reactie$$,
   $$biologie-vwo-2026-i-imker-door-bijensteken-naar-de-eerste-hulp-context4.png$$,
   $$Bert was al enkele keren eerder door zijn bijen gestoken, maar toen was er geen sprake van een allergische reactie.$$, 'inline'),
  ('0593938b-59ca-44e7-ad93-e299ae98529d', '58a83532-6fbe-4f00-86da-47ecf3f6d400', $$na een bijensteek kan de bloeddruk zo ver dalen dat er geen polsslag te voelen is$$,
   $$biologie-vwo-2026-i-imker-door-bijensteken-naar-de-eerste-hulp-context5.png$$,
   $$Na een bijensteek kan de bloeddruk zo ver dalen dat er geen polsslag te voelen is. In de ambulance werden Berts hartslag en bloeddruk gemeten. Zijn bloeddruk was heel laag.$$, 'inline'),
  ('5946d173-3816-4d96-b3ad-769aac79a331', '58a83532-6fbe-4f00-86da-47ecf3f6d400', $$mellitine (hoofdbestanddeel van bijengif) bestaat uit 26 aminozuren; ruimtelijke structuur en vorming van de tertiaire structuur door hydrofobe interacties, zwavelbruggen en waterstofbruggen$$,
   $$biologie-vwo-2026-i-imker-door-bijensteken-naar-de-eerste-hulp-context6.png$$,
   $$De pijn van een bijensteek wordt veroorzaakt door mellitine, het hoofdbestanddeel van bijengif.
Mellitine is opgebouwd uit 26 aminozuren. De aminozuurvolgorde van mellitine is:
GIGAVLKVLTTGLPALISWIKRKRQQ
Hiernaast zie je de ruimtelijke structuur van dit eiwit. Daarin zijn zes aminozuren met hun letters aangegeven.
In de volgende afbeelding zie je hoe de tertiaire structuur van eiwitten wordt gevormd door hydrofobe interacties (1), door zwavelbruggen (2) en door waterstofbruggen (3).$$, 'inline'),
  ('c88bd668-c097-4540-8aca-702549b1ce78', '58a83532-6fbe-4f00-86da-47ecf3f6d400', $$één van deze interacties speelt geen rol bij de tertiaire structuur van mellitine$$,
   $$biologie-vwo-2026-i-imker-door-bijensteken-naar-de-eerste-hulp-context7.png$$,
   $$Uit de primaire structuur van mellitine is af te leiden dat een van deze interacties geen rol speelt bij de vorming van de tertiaire structuur.$$, 'inline'),
  ('05011e1a-86b2-484e-b6ed-a5925b538707', '58a83532-6fbe-4f00-86da-47ecf3f6d400', $$het middelste deel van mellitine (GLPALI) bestaat uit aminozuren met apolaire restgroepen$$,
   $$biologie-vwo-2026-i-imker-door-bijensteken-naar-de-eerste-hulp-context8.png$$,
   $$Het middelste deel van het eiwit (met de sequentie GLPALI) bestaat uit aminozuren met apolaire restgroepen. Mellitine komt terecht in de celmembraan. Een deel van het eiwit bevindt zich dan binnen de cel, en een ander deel steekt uit buiten de cel.$$, 'inline'),
  ('e42b4f85-a6f2-4007-adca-47dba40f3204', '58a83532-6fbe-4f00-86da-47ecf3f6d400', $$mellitine opent na opname in de celmembraan van een pijnreceptor de calciumkanaaltjes, wat leidt tot een impuls$$,
   $$biologie-vwo-2026-i-imker-door-bijensteken-naar-de-eerste-hulp-context9.png$$,
   $$Nadat mellitine is opgenomen in de celmembraan van een pijnreceptor, opent die – via een aantal stappen – de calciumkanaaltjes. De diffusie van Ca²⁺ door calciumkanaaltjes leidt bij pijnreceptoren tot het ontstaan van een impuls.$$, 'inline'),
  ('65d74228-6640-442c-91c8-8d2d486f2351', '58a83532-6fbe-4f00-86da-47ecf3f6d400', $$signaaloverdracht na binding van mellitine tot het openen van de calciumkanaaltjes, met stoffen P en Q$$,
   $$biologie-vwo-2026-i-imker-door-bijensteken-naar-de-eerste-hulp-context10.png$$,
   $$De onderstaande afbeelding toont hoe na binding van mellitine het signaal wordt doorgegeven zodat de calciumkanaaltjes opengaan.$$, 'inline'),
  ('a42f0f12-1002-4363-bf78-5bcafaa09f10', '58a83532-6fbe-4f00-86da-47ecf3f6d400', $$de stoffen P en Q vervullen een bepaalde functie in de signaaloverdracht$$,
   $$biologie-vwo-2026-i-imker-door-bijensteken-naar-de-eerste-hulp-context11.png$$,
   $$De stoffen P en Q in de afbeelding vervullen een bepaalde functie in de signaaloverdracht.$$, 'inline'),
  ('3b78cf27-f8a4-4eac-8968-f719534da6e3', '58a83532-6fbe-4f00-86da-47ecf3f6d400', $$diffusie van Ca²⁺ door de calciumkanaaltjes verandert de membraanpotentiaal$$,
   $$biologie-vwo-2026-i-imker-door-bijensteken-naar-de-eerste-hulp-context12.png$$,
   $$De diffusie van Ca²⁺ door de calciumkanaaltjes leidt tot een verandering van de membraanpotentiaal.$$, 'inline'),
  ('3c9bed68-ce33-417a-a99a-d74a41c99cf4', '58a83532-6fbe-4f00-86da-47ecf3f6d400', $$de adrenalinepen dient om een levensbedreigende bloeddrukdaling te voorkomen; effecten van adrenaline$$,
   $$biologie-vwo-2026-i-imker-door-bijensteken-naar-de-eerste-hulp-context13.png$$,
   $$De arts schrijft een adrenalinepen voor. Als Bert dan nog eens gestoken wordt, kan hij zichzelf daarmee meteen adrenaline toedienen zodat er geen levensbedreigende verlaging van de bloeddruk kan optreden. Hieronder staan enkele effecten van adrenaline.
1 samentrekking van glad spierweefsel in de slagadertjes
2 toename van de doorbloeding van skeletspieren
3 toename van de hartslagfrequentie
4 verwijding van de bronchiën$$, 'inline'),
  ('cc998ddf-5caa-49e7-8e48-c5a5d300bfb4', '4d01e2c8-3f82-43ae-b31d-0ee6388ccc83', $$inleiding: onderzoek of de CRISPR-techniek diabetes type 2 kan tegengaan door witte vetcellen in beige vetcellen te veranderen$$,
   $$biologie-vwo-2026-i-crispr-in-de-strijd-tegen-overgewicht-context1.png$$,
   $$Obesitas (een ernstige vorm van overgewicht) is een aandoening die kan leiden tot hart- en vaatziekten en diabetes type 2. Wetenschappers hebben onderzocht of de CRISPR-techniek kan worden gebruikt om diabetes type 2 tegen te gaan. Met deze techniek veranderden ze menselijke witte vetcellen in beige vetcellen.$$, 'inline'),
  ('a61aa2f8-d4bb-4343-8833-921fbcaf9f92', '4d01e2c8-3f82-43ae-b31d-0ee6388ccc83', $$informatiekader: drie typen vetcellen – witte, bruine en beige vetcellen – en hun functie$$,
   $$biologie-vwo-2026-i-crispr-in-de-strijd-tegen-overgewicht-context2.png$$,
   $$In het menselijk lichaam komen drie typen vetcellen voor:
1 Witte vetcellen: deze slaan vet op als reservestof voor ATP-productie.
2 Bruine vetcellen: deze slaan vet op voor warmteproductie. Bij blootstelling aan kou wordt het vet verbrand om warmte te produceren. Bruine vetcellen zijn geclusterd aanwezig tussen de schouderbladen, rond het hart en langs de grote bloedvaten.
3 Beige vetcellen: deze vetcellen hebben dezelfde functie als bruine vetcellen, maar zijn verspreid aanwezig in andere weefsels (zoals in spierweefsel). Deze vetcellen waren oorspronkelijk witte vetcellen die door een toename van het aantal mitochondriën lichtbruin zijn geworden.$$, 'inline'),
  ('8131bb0b-8a73-4b08-b075-32fee41dcefe', '4d01e2c8-3f82-43ae-b31d-0ee6388ccc83', $$informatiekader: bij obese mensen is bruin vetweefsel niet tot nauwelijks aanwezig (afbeelding 1)$$,
   $$biologie-vwo-2026-i-crispr-in-de-strijd-tegen-overgewicht-context3.png$$,
   $$Bij obese mensen is bruin vetweefsel niet tot nauwelijks aanwezig. In afbeelding 1 is de activiteit van bruin vetweefsel zichtbaar gemaakt bij twee proefpersonen, nadat zij twee uur lang zijn blootgesteld aan kou. In de linker foto is bij een slanke persoon de aanwezigheid van bruin vetweefsel goed zichtbaar. De rechter foto is van een obese persoon.
afbeelding 1$$, 'inline'),
  ('663c8cdf-ec34-48eb-bc8e-37b5dc4b52f6', '4d01e2c8-3f82-43ae-b31d-0ee6388ccc83', $$obesitas kan zowel oorzaak als gevolg zijn van de afwezigheid van bruin vetweefsel$$,
   $$biologie-vwo-2026-i-crispr-in-de-strijd-tegen-overgewicht-context4.png$$,
   $$Obesitas zou een oorzaak, maar ook een gevolg kunnen zijn van de afwezigheid van bruin vetweefsel bij obese mensen.$$, 'inline'),
  ('b5cc30c8-38ce-4d8a-9af6-95f7c42d25f5', '4d01e2c8-3f82-43ae-b31d-0ee6388ccc83', $$informatiekader: het UCP1-eiwit laat H⁺-ionen terug naar de matrix diffunderen zonder ATP-productie$$,
   $$biologie-vwo-2026-i-crispr-in-de-strijd-tegen-overgewicht-context5.png$$,
   $$In bruine en beige vetcellen komt het UCP1-gen tot expressie. Het UCP1- eiwit (uncoupling protein 1) komt terecht in de mitochondriën. Tijdens de oxidatieve fosforylering kunnen H⁺-ionen dan via het UCP1-eiwit terug naar de matrix diffunderen, waardoor er geen ATP maar alleen warmte wordt geproduceerd.$$, 'inline'),
  ('071df64c-4f4c-495a-b2c9-96b8bc3bba77', '4d01e2c8-3f82-43ae-b31d-0ee6388ccc83', $$het UCP1-gen ligt op chromosoom 4; het eiwit vouwt pas na import in de mitochondriën$$,
   $$biologie-vwo-2026-i-crispr-in-de-strijd-tegen-overgewicht-context6.png$$,
   $$Het UCP1-gen bevindt zich op chromosoom 4. Na de translatie komt het eiwit in ongevouwen toestand terecht in het grondplasma. Daar wordt het herkend door speciale eiwitten op de mitochondriën. Deze eiwitten brengen het daarna in de mitochondriën, en plaatsen het met de juiste vouwing in de binnenmembraan.$$, 'inline'),
  ('38fd65ad-004f-4a8f-af94-24bf7043ebbb', '4d01e2c8-3f82-43ae-b31d-0ee6388ccc83', $$informatiekader: met CRISPR wordt het UCP1-gen tot expressie gebracht in witte vetcellen, die daardoor beige worden$$,
   $$biologie-vwo-2026-i-crispr-in-de-strijd-tegen-overgewicht-context7.png$$,
   $$Als obese mensen meer bruin of beige vetweefsel zouden hebben, zou dat misschien kunnen helpen tegen overgewicht. Onderzoekers zijn erin geslaagd om in het laboratorium menselijke witte vetcellen te veranderen in beige vetcellen. Ze gebruikten hiervoor een variant van de CRISPR- techniek, waarmee ze in witte vetcellen het UCP1-gen tot expressie kunnen brengen. De witte vetcellen worden op deze manier veranderd in beige vetcellen.$$, 'inline'),
  ('af926c20-f1d7-41dc-9804-8a2be68e0600', '4d01e2c8-3f82-43ae-b31d-0ee6388ccc83', $$ingebracht DNA bevat de code voor Cas-eiwit met activator-eiwitten en gids-RNA dat aan de UCP1-promotor bindt (afbeelding 2)$$,
   $$biologie-vwo-2026-i-crispr-in-de-strijd-tegen-overgewicht-context8.png$$,
   $$De onderzoekers brachten met een virus een stuk DNA in het genoom van witte vetcellen. Dit DNA bevat:
− de genetische code voor een speciaal Cas-eiwit met activator-eiwitten (transcriptiefactoren);
− de genetische code voor het RNA dat aan de promotor van het UCP1- gen kan hechten (gids-RNA). Wanneer het Cas-eiwit met de activator-eiwitten en het gids-RNA door een cel zijn gemaakt, schakelen deze moleculen het UCP1-gen aan. Hierdoor gaat een witte vetcel het UCP1-eiwit produceren (afbeelding 2).
afbeelding 2$$, 'inline'),
  ('abdcf857-9fd3-4b16-a377-8cde0b2fd489', '4d01e2c8-3f82-43ae-b31d-0ee6388ccc83', $$informatiekader: proefopzet met drie groepen obese muizen die witte, beige of bruine vetcellen getransplanteerd kregen$$,
   $$biologie-vwo-2026-i-crispr-in-de-strijd-tegen-overgewicht-context9.png$$,
   $$Het effect van de beige vetcellen werd getest in muizen die al twaalf weken lang een vetrijk dieet hadden gekregen en inmiddels obees waren geworden. Deze muizen werden in drie groepen verdeeld en kregen verschillende menselijke cellen getransplanteerd tussen de schouderbladen:
− groep 1: witte vetcellen;
− groep 2: beige vetcellen (met CRISPR gemaakt);
− groep 3: bruine vetcellen. Gedurende vier weken werd het lichaamsgewicht bepaald. De muizen werden gehouden bij kamertemperatuur en hielden al die tijd hun vetrijke dieet.$$, 'inline'),
  ('2cb84aaa-0454-4568-8b01-57236dd5bdda', '4d01e2c8-3f82-43ae-b31d-0ee6388ccc83', $$de gebruikte muizen zijn immunodeficiënt$$,
   $$biologie-vwo-2026-i-crispr-in-de-strijd-tegen-overgewicht-context10.png$$,
   $$De muizen die voor dit onderzoek zijn gebruikt, hebben een uitgeschakeld immuunsysteem: ze zijn immunodeficiënt.$$, 'inline'),
  ('c7094c33-0fa3-428c-94e2-f9aeea72eea2', '4d01e2c8-3f82-43ae-b31d-0ee6388ccc83', $$verandering in lichaamsgewicht van de drie groepen (afbeelding 3)$$,
   $$biologie-vwo-2026-i-crispr-in-de-strijd-tegen-overgewicht-context11.png$$,
   $$De verandering in lichaamsgewicht van de drie groepen is weergegeven in afbeelding 3.
afbeelding 3$$, 'inline'),
  ('244c3eb8-71ba-4e6a-af0d-24c3b8425a26', '4d01e2c8-3f82-43ae-b31d-0ee6388ccc83', $$glucosetolerantietest bij de drie groepen muizen na vier weken; concentratie insuline (afbeelding 4)$$,
   $$biologie-vwo-2026-i-crispr-in-de-strijd-tegen-overgewicht-context12.png$$,
   $$Obesitas kan leiden tot ongevoeligheid voor insuline (diabetes type 2). Bij de muizen in het experiment werd na vier weken een glucosetolerantietest uitgevoerd. De muizen kregen zes uur lang geen eten en kregen daarna een injectie met een standaardhoeveelheid glucose. Tot 90 minuten na de injectie werd het verloop van de glucoseconcentratie van het bloed gemeten (afbeelding 4). Ook werd de concentratie insuline bepaald. Hierin was geen verschil tussen de drie groepen.
afbeelding 4$$, 'inline'),
  ('06037483-3bab-4733-a3a1-df80231d04c4', '479ada19-7ce1-466a-b64d-3e5f44dfba79', $$inleiding: onderzoek van de Rijksuniversiteit Groningen naar zetmeelmatten voor het herstel van kust-ecosystemen$$,
   $$biologie-vwo-2026-i-zetmeelmatten-voor-de-kust-context1.png$$,
   $$Wereldwijd worden kust-ecosystemen aangetast door klimaatverandering en andere menselijke invloeden. Wetenschappers van de Rijksuniversiteit Groningen doen onderzoek naar de effectiviteit van het gebruik van zetmeelmatten bij het herstel van deze ecosystemen.$$, 'inline'),
  ('26e5e3e4-5275-4d4c-a88b-e78945b03795', '479ada19-7ce1-466a-b64d-3e5f44dfba79', $$informatiekader: biobouwers zoals zeegras en slijkgras beïnvloeden hun omgeving positief (afbeelding 1, afbeelding 2); effect op waterstroming, sediment en biodiversiteit$$,
   $$biologie-vwo-2026-i-zetmeelmatten-voor-de-kust-context2.png$$,
   $$Kust-ecosystemen zijn belangrijk als kraamkamer voor mariene organismen en voor kustbescherming en recreatie. Veel kust-ecosystemen worden gevormd door ‘biobouwers’ (ecosystem engineers). Dit zijn soorten die het milieu waarin zij voorkomen in sterke mate positief beïnvloeden. Voorbeelden zijn zeegrassoorten (Zostera sp., afbeelding 1) die uitgestrekte velden vormen op ondiepe plekken langs de kust, en slijkgrassoorten (Sporobolus sp., afbeelding 2) die alleen bij hoogwater onder water staan.
afbeelding 1 afbeelding 2
Zeegras- en slijkgrasvelden zijn een belangrijk onderdeel van kust- ecosystemen. Deze velden remmen de waterstroming, waardoor zand en slib kunnen bezinken. Hun wortelstelsels stabiliseren het sediment, waardoor ook andere planten zich kunnen vestigen. Hierdoor neemt de biodiversiteit toe.$$, 'inline'),
  ('55169793-20ba-4058-94f5-948144a44e22', '479ada19-7ce1-466a-b64d-3e5f44dfba79', $$klimaatverandering heeft negatieve gevolgen voor biobouwers zoals zeegras en slijkgras$$,
   $$biologie-vwo-2026-i-zetmeelmatten-voor-de-kust-context3.png$$,
   $$Klimaatverandering heeft verschillende gevolgen die een negatieve invloed hebben op biobouwers zoals zeegras en slijkgras. Hierdoor worden kust- ecosystemen aangetast.$$, 'inline'),
  ('e033e0aa-7d0d-4bf2-a389-0084707f4747', '479ada19-7ce1-466a-b64d-3e5f44dfba79', $$de netto primaire productie van kust-ecosystemen is hoger dan die van de open oceaan; uitspraken over kust-ecosystemen$$,
   $$biologie-vwo-2026-i-zetmeelmatten-voor-de-kust-context4.png$$,
   $$De netto primaire productie (NPP) in kust-ecosystemen is hoger dan die van een gelijke oppervlakte midden op de oceaan. Dat komt doordat in kust-ecosystemen veel meer fotosynthese plaatsvindt. Hieronder staan uitspraken over kust-ecosystemen.
1 Kust-ecosystemen dragen meer bij aan de opname van koolstof in organische stoffen dan een gelijke oppervlakte midden op de oceaan.
2 De BPP van kust-ecosystemen is hoger dan die van de open oceaan.
3 De aanwezigheid van biobouwers vergroot het aantal niches in een kust-ecosysteem.$$, 'inline'),
  ('ebc32998-a339-471e-a728-a9e964f353ef', '479ada19-7ce1-466a-b64d-3e5f44dfba79', $$informatiekader: aantasting van een zeegrasveld kan leiden tot een omslagpunt en een blijvend veranderd ecosysteem (afbeelding 3)$$,
   $$biologie-vwo-2026-i-zetmeelmatten-voor-de-kust-context5b.png$$,
   $$Aantasting van zeegrasvelden kan ertoe leiden dat het ecosysteem compleet verandert. In afbeelding 3 is deze verandering weergegeven. Als een zeegrasveld (fase 1) wordt aangetast, kan dit leiden tot een omslagpunt (fase 2). Hierdoor raakt het ecosysteem blijvend veranderd (fase 3), en is herstel naar fase 1 heel erg moeilijk.
afbeelding 3
zeegras zeegras en algen algen$$, 'inline'),
  ('1d2559e7-11e0-4df3-b65a-f71ce3828606', '479ada19-7ce1-466a-b64d-3e5f44dfba79', $$drie uitspraken over het aantastingsproces van zeegrasvelden$$,
   $$biologie-vwo-2026-i-zetmeelmatten-voor-de-kust-context6.png$$,
   $$Hieronder staan uitspraken over het aantastingsproces van zeegrasvelden.
1 In fase 2 is sprake van een evenwichtssituatie.
2 De groei van zeegras stimuleert de opwerveling van sediment.
3 Fase 3 is een climax-ecosysteem.$$, 'inline'),
  ('0c20afa9-28e5-4bec-9b95-835bf155b42e', '479ada19-7ce1-466a-b64d-3e5f44dfba79', $$informatiekader: zetmeelmatten geven structuur waaraan zeegras en slijkgras zich kunnen hechten (afbeelding 4)$$,
   $$biologie-vwo-2026-i-zetmeelmatten-voor-de-kust-context7.png$$,
   $$Het herstel van zeegras- en slijkgrasvelden mislukt vaak doordat structuren ontbreken waaraan zij zich kunnen hechten. Bij de kust van Bonaire en de kust van Texel werd onderzocht of het plaatsen van zetmeelmatten (afbeelding 4) effectief is voor het herstel van zeegras- en slijkgrasvelden.
afbeelding 4
van bovenaf gezien vanaf de zijkant gezien$$, 'inline'),
  ('fe285db7-daf8-4ad9-afb4-2b715004c1d0', '479ada19-7ce1-466a-b64d-3e5f44dfba79', $$zetmeelmatten zijn gemaakt van aardappelafval, geen voedsel voor mens of dier$$,
   $$biologie-vwo-2026-i-zetmeelmatten-voor-de-kust-context8.png$$,
   $$De zetmeelmatten zijn gemaakt van aardappelafval. Daardoor worden er geen producten gebruikt die anders als eten voor mensen of dieren gebruikt zouden kunnen worden.$$, 'inline'),
  ('71c3a653-56d5-4e0c-96e0-442a13ef2ec0', '479ada19-7ce1-466a-b64d-3e5f44dfba79', $$informatiekader: twee hypothesen over het effect van zetmeelmatten op de overleving en groei van slijkgras en zeegras; onderzoeksmethode$$,
   $$biologie-vwo-2026-i-zetmeelmatten-voor-de-kust-context9.png$$,
   $$Zetmeelmatten kunnen op de zeebodem geplaatst worden om de waterbeweging af te zwakken. Ze kunnen ook net onder het bodemoppervlak geplaatst worden om het sediment te stabiliseren. De onderzoekers hadden twee hypothesen geformuleerd:
1 Zetmeelmatten op de zeebodem hebben een positief effect op de overleving en de groei van slijkgras.
2 Zetmeelmatten onder het bodemoppervlak hebben een positief effect op de overleving en de groei van zeegras. Om deze hypotheses te testen, werden zetmeelmatten aangebracht in de proefgebieden en werden er daarna jonge planten (slijkgras of zeegras) geplant in de matten. Als controle werd hetzelfde aantal jonge planten op een oppervlak zonder zetmeelmatten geplant. Na ruim twaalf maanden werd de overleving van de jonge planten bepaald. De groei werd bepaald door het aantal nieuwe scheuten van deze planten te tellen per zetmeelmat of per controle-oppervlak.$$, 'inline'),
  ('9b06a456-7e30-484b-ad24-77ce34c33379', '479ada19-7ce1-466a-b64d-3e5f44dfba79', $$informatiekader: resultaten van het experiment bij Bonaire en bij Texel (afbeelding 5)$$,
   $$biologie-vwo-2026-i-zetmeelmatten-voor-de-kust-context10.png$$,
   $$De resultaten van het experiment bij Bonaire en bij Texel zijn weergegeven in afbeelding 5.
afbeelding 5$$, 'inline'),
  ('7e28685e-8771-42a7-a8f1-172f2778a3a8', '479ada19-7ce1-466a-b64d-3e5f44dfba79', $$drie uitspraken over de resultaten in afbeelding 5$$,
   $$biologie-vwo-2026-i-zetmeelmatten-voor-de-kust-context11.png$$,
   $$Hieronder staan uitspraken over de resultaten in afbeelding 5.
1 De resultaten ondersteunen hypothese 1 en hypothese 2.
2 De resultaten bewijzen dat zetmeelmatten onder het bodemoppervlak het sediment stabiliseren.
3 De resultaten laten zien dat bij Texel beter kan worden gekozen voor zeegras dan voor slijkgras.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('c0d71a1c-555a-4bc7-b7a2-eff78ecee8e7', 'af9190b3-307d-450e-b4cc-2862af1a70e6', 1,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Zelfregulatie van het organisme"}]'::jsonb,
   '["bloedplaatjes", "cell junctions", "endotheelcellen", "bloedvatwand", "doorlaatbaarheid"]'::jsonb,
   $$Verklaren hoe een tekort aan bloedplaatjes tot bloeduitstortingen in de huid leidt.$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-vraag1.png$$, $$2p 1 Leg uit – aan de hand van dit gegeven – hoe de bloeduitstortinkjes in Rosies huid ontstaan.$$, array['f2491363-89fd-4ce3-8285-ccaef940f434', '31898dfd-969c-4dda-83d8-45879c4775af', '8dc4ca11-6f80-4e02-b90c-3b700895f60a']::uuid[]),
  ('3e697fa4-063e-417d-88c7-a9563e4bbf56', 'af9190b3-307d-450e-b4cc-2862af1a70e6', 2,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Zelfregulatie van het organisme"}]'::jsonb,
   '["TPO", "negatieve terugkoppeling", "megakaryoblasten", "hormonale regulatie"]'::jsonb,
   $$Bepalen hoe de TPO-concentratie verandert bij een toename van bloedplaatjes en welk type terugkoppeling dit is.$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-vraag2.png$$, $$2p 2 Neemt door een toename van het aantal bloedplaatjes de TPO- concentratie af of toe? En is deze regulatie van de concentratie bloedplaatjes een voorbeeld van negatieve terugkoppeling of van positieve terugkoppeling?
TPO-concentratie terugkoppeling
A neemt af negatief
B neemt af positief
C neemt toe negatief
D neemt toe positief$$, array['00e17aaa-6804-4c84-9228-086c904e9988']::uuid[]),
  ('2fe368d6-ce2c-4088-a5b7-3408b7a17a96', 'af9190b3-307d-450e-b4cc-2862af1a70e6', 3,
   '[{"domain": "Orgaan- en organismeniveau", "subdomain": "Zelfregulatie van het organisme"}]'::jsonb,
   '["bloedplaatjestelling", "microscopisch preparaat", "referentiewaarden", "informatieboek"]'::jsonb,
   $$Schatten van het aantal bloedplaatjes in het bloed van Rosie op basis van een microscopisch preparaat.$$,
   $$biologie-vwo-2026-i-bloedplaatjes-belaagd-vraag3.png$$, $$2p 3 Hoeveel bloedplaatjes zijn ongeveer aanwezig in een mm³ bloed van Rosie? Gebruik je informatieboek.
A 3
B 30
C 300
D 3.000
